style.css:
/* Cyber Pink */
body { background: #FFF0FA !important; color: #49233F !important; }
h1, h2, h3 { color: #D60078 !important; }
p { color: #79516F !important; }
a { color: #E6008A !important; }
button {
  background: #FF1493 !important;
  color: white !important;
  border: 1px solid #D60078 !important;
  border-radius: 5px !important;
}
input, textarea {
  background: #FFE0F1 !important;
  color: #49233F !important;
  border: 1px solid #FF8CCB !important;
}
::selection { background: #FF1493; color: white; }
